export type InterruptionView = { at_unix: number; reason: string }
export type JsonValue = null | boolean | number | string | JsonValue[] | Partial<{ [key in string]: JsonValue }>
export type Listener = { id: ListenerId; name: string; listener_type: ListenerType; listen: string; port: number; auth: Auth | null; exit: ExitId | null; user_enabled: boolean; routing?: ListenerRouting | null; hidden?: boolean }
export type ListenerId = string
/**
 * Per-port routing; None preserves legacy uniform forwarding.
 */
export type ListenerRouting = { rules: PortRule[]; unmatched: RuleAction }
export type ListenerStatus = "Active" | "DisabledByUser" | "NoExit" | { ExitBroken: { exit_status: ExitStatus } }
export type ListenerType = "Mixed" | "Http" | "Socks"
/**
 * 手动添加的节点。组成员关系存在节点上（`groups`）。
 */
export type ManualNode = { id: ManualNodeId; name: string; groups: NodeGroupId[]; kind: ManualNodeKind }
export type ManualNodeId = string
export type ManualNodeKind = 
/**
 * 原样的 mihomo proxy 映射
 */
{ Proxy: { raw: JsonValue } } | { Tailscale: TailscaleOpts }
export type Model = { subscriptions: Subscription[]; exits: Exit[]; listeners: Listener[]; settings: Settings; manual_nodes: ManualNode[]; node_groups: NodeGroup[]; process_routing: ProcessRouting }
/**
 * Why a target failed a round.
 */
export type MonitorFailure = "Timeout" | "Failed" | { OverLimit: number }
/**
 * Where clicking a notice leads.
 */
export type MonitorFocus = { Node: NodeRef } | "Listeners" | "Settings"
export type MonitorNotice = { title: string; body: string; focus: MonitorFocus }
export type MonitorPause = "CoreNotRunning" | 
/**
 * The last apply failed and the core kept the previous config.
 */
"ConfigNotApplied"
export type MonitorStatus = { last_run: number | null; next_run: number | null; probing: boolean; paused_reason: MonitorPause | null; network_down: boolean; targets: MonitorTarget[] }
export type MonitorTarget = { proxy: string; node: NodeRef | null; label: string; used_by: string[]; 
/**
 * Consecutive failed rounds.
 */
fails: number; down: boolean; 
/**
 * Unix seconds.
 */
down_since: number | null; 
/**
 * Latency of the last measured round (also set when over the limit).
 */
last_ms: number | null; last_failure: MonitorFailure | null; 
/**
 * At least one round produced a usable result.
 */
probed: boolean; 
/**
 * mihomo has no proxy by that name (exit not applied).
 */
not_applied: boolean }
export type NetInterface = { 
/**
 * Adapter GUID exactly as Windows reports it, e.g. `{XXXXXXXX-...}`.
 */
guid: InterfaceGuid; friendly_name: string; description: string; is_up: boolean; ipv4: string[]; ipv6: string[]; 
/**
 * Value for mihomo's `interface-name`: the friendly name verbatim,
 * case preserved (spike S1: GUID and description do not work).
 */
mihomo_name: string }
export type Node = { name: string; proxy_type: string; server: string; 
/**
 * 原样的 mihomo proxy 映射
 */
raw: JsonValue }
export type NodeGroup = { id: NodeGroupId; name: string; members?: NodeRef[] }
export type NodeGroupId = string
export type NodeMonitorSettings = { enabled: boolean; 
/**
 * 监测的节点或整组；首次开启时前端用当前正在使用的节点预填。
 */
members: ExitMember[]; interval_secs: number; fail_threshold: number; 
/**
 * None = 不限
 */
latency_limit_ms: number | null; notify_recovery: boolean }
/**
 * 指向一个节点。untagged：旧 JSON `{subscription_id, name}` 直接落到
 * `Subscription` 变体，存回去的形状也不变。
 */
export type NodeRef = { subscription_id: SubscriptionId; name: string } | { manual_id: ManualNodeId }
/**
 * A pasted proxy, ready to become `ManualNodeKind::Proxy { raw }`.
 */
export type ParsedProxy = { raw: JsonValue; 
/**
 * Keys removed from the paste, a subset of
 * `["interface-name", "routing-mark", "dialer-proxy"]` in that order.
 */
stripped: string[] }
export type PortRule = { matcher: RuleMatch; value: string; action: RuleAction }
export type ProcRouteStatus = { component: ComponentState; 
/**
 * 当前启用规则的服务确认结果；未确认时为 Pending / Failed / Unknown。
 */
actions: Partial<{ [key in ProcessRuleId]: RuleView }>; last_interruption: InterruptionView | null; conflicts: string[]; 
/**
 * 最近一次应用错误；由用户主动重试。
 */
apply_errors: string[]; 
/**
 * 连接列表达到服务的上限、被截断了（界面标明"仅显示最近 400 条"）。
 */
truncated_flows: boolean }
/**
 * 规则里的一个程序：按进程名（`a.exe`）或完整路径（`C:\…\a.exe`）匹配。
 */
export type ProcessEntry = { kind: ProcessKind; value: string }
/**
 * 规则里 `exe_path` 的含义。
 */
export type ProcessKind = "Name" | "Path"
export type ProcessRouting = { enabled: boolean; rules: ProcessRule[]; 
/**
 * 退出 Routa 时是否提示（默认提示）。
 */
exit_prompt: boolean }
/**
 * 按进程分流的一条规则：一组程序的流量走某个 Listener。
 */
export type ProcessRule = { id: ProcessRuleId; 
/**
 * 显示名称；为空时界面用第一个进程名代替。
 */
name: string; 
/**
 * 规则里的程序，每个条目自带匹配方式。
 */
processes: ProcessEntry[]; 
/**
 * 按进程名匹配的条目已知的完整路径（服务从连接里学到），用于 WFP 守护。
 */
learned: string[]; 
/**
 * 直接选择的节点；设置后由程序自动管理隐藏监听器。
 */
node?: NodeRef | null; 
/**
 * 出站网卡（仅 `node` 模式使用）。
 */
interface?: InterfaceGuid | null; on_fault: FaultPolicy; reset_on_change: boolean; user_enabled: boolean; ai_app: string | null }
export type ProcessRuleId = string
/**
 * A project page linked from Settings → About; the URLs live here so the
 * frontend can only open these two.
 */
export type ProjectLink = "Website" | "GitHub"
/**
 * Bytes per second.
 */
export type Rate = { up: number; down: number }
export type RuleAction = "Proxy" | "Direct" | "Reject"
export type RuleMatch = "Domain" | "DomainSuffix" | "Ipv4Cidr"
/**
 * Why the rule dialog's save failed: field errors for the form, or a message.
 */
export type RuleSaveError = ValidationError[] | string
export type RuleView = { 
/**
 * "Proxy" | "Direct" | "Block" | "Pending" | "Failed" | "Unknown"
 */
action: string; 
/**
 * 回落、执行失败或无法确认状态的原因（中文）。
 */
reason: string | null; up_bps: number; down_bps: number }
export type RunningProcess = { pid: number; 
/**
 * exe 文件名。
 */
name: string; exe_path: string }
export type RuntimeStatus = { core: CoreState; last_apply: ApplyOutcome | null; health: Health; delays: DelayBook; traffic: TrafficTick | null; interfaces: NetInterface[]; failed_listeners: FailedListener[]; 
/**
 * Listeners in the config mihomo currently holds (empty when no core
 * runs or after a fail-closed apply). An active listener missing here is
 * not in effect, whatever `last_apply` says.
 */
effective_listeners: ListenerId[]; 
/**
 * Problems found while loading persisted state (e.g. a corrupt state.json
 * that was moved aside).
 */
startup_error: string | null; 
/**
 * Last state.json / traffic.json save failure; cleared once that file
 * saves successfully again.
 */
save_error: string | null; 
/**
 * Login state per Tailscale proxy name (`手动/<名>`), from the log of
 * the current mihomo process; empty while no core runs.
 */
tailscale: Partial<{ [key in string]: TailscaleState }>; 
/**
 * Per Tailscale proxy name: why mihomo could not apply its `exit-node`
 * (until that instance restarts).
 */
tailscale_exit_errors: Partial<{ [key in string]: string }>; 
/**
 * Per Tailscale proxy name: the automatic retry (1..=EXIT_NODE_MAX_RETRIES)
 * scheduled for its exit node failure. A failure without an entry here is final.
 */
tailscale_exit_retrying: Partial<{ [key in string]: number }>; 
/**
 * Why Routa last stopped the core itself; `None` once a start succeeds
 * (and before any stop). `shutdown` leaves it as it was.
 */
core_stop_reason: CoreStopReason | null; 
/**
 * The core exited unexpectedly and has not reached `Running` since: a
 * `Starting` in this state is a recovery, not a normal start. Not set by
 * a fail-closed stop (`core_stop_reason` says `FailClosed` instead).
 */
core_recovering: boolean; 
/**
 * Node monitor snapshot (targets, round timing, network verdict).
 */
monitor: MonitorStatus }
export type Settings = { autostart: boolean; core_path: string | null; controller_port: number; delay_test_interval_mins: number | null; delay_test_url: string; node_monitor: NodeMonitorSettings }
export type SettingsSaveError = ValidationError[] | string
export type Subscription = { id: SubscriptionId; name: string; url: string; update_interval_mins: number | null; fallback_exit: ExitId | null; fallback_listener?: ListenerId | null; 
/**
 * unix 秒
 */
last_updated: number | null; last_result: FetchResult | null; nodes: Node[] }
export type SubscriptionId = string
export type TailnetPeer = { 
/**
 * The machine's requested hostname (what a Tailscale instance's
 * `hostname` registers as).
 */
host_name: string; 
/**
 * MagicDNS name without the trailing dot.
 */
dns_name: string; ips: string[]; online: boolean; 
/**
 * Advertises itself as an exit node and is approved for this tailnet.
 */
exit_node_option: boolean }
export type TailscaleOpts = { hostname: string; exit_node: string; ephemeral: boolean; udp: boolean; auth_key: string | null; 
/**
 * None = 走系统默认网卡
 */
interface: InterfaceGuid | null }
export type TailscaleState = "Unknown" | { NeedsLogin: { url: string | null } } | { LoggedIn: { ip: string | null } } | { Failed: { reason: string } }
export type TaskbarStatusMode = "Rotate" | { Fixed: ListenerId }
export type TaskbarStatusPrefs = { enabled: boolean; mode: TaskbarStatusMode; traffic: TaskbarTraffic }
/**
 * The bar shows one of the two, to stay narrow.
 */
export type TaskbarTraffic = "Values" | "Chart"
export type TrafficTick = { total_rate: Rate; 
/**
 * Every listener that had a delta in this tick.
 */
per_listener_rate: Partial<{ [key in ListenerId]: Rate }>; 
/**
 * Connections captured by TUN; they belong to no listener.
 */
tun_rate: Rate; totals: TrafficTotals }
export type TrafficTotals = { total: Bytes; per_listener: Partial<{ [key in ListenerId]: Bytes }> }
export type UiPreferences = { mode: InterfaceMode | null; listener_id: ListenerId | null; exit_id: ExitId | null; system_listener_id: ListenerId | null; capture_mode: CaptureMode; auto_connect: boolean; close_to_tray: boolean; managed_rules: ProcessRuleId[]; selected_apps: ProcessRuleId[]; taskbar_status: TaskbarStatusPrefs }
export type UpdateState = 
/**
 * Not an NSIS install (dev build or unpacked exe): no updates.
 */
{ kind: "Unsupported" } | { kind: "Idle" } | { kind: "Checking" } | { kind: "Downloading"; version: string; received: number; total: number | null } | 
/**
 * A verified installer for `version` is in the cache.
 */
{ kind: "Ready"; version: string; notes: string | null } | { kind: "Failed"; message: string }
export type UpdateView = { current_version: string; state: UpdateState; last_checked_unix: number | null }
export type ValidationError = { DuplicateName: { kind: string; name: string } } | { PortConflict: { port: number; with: string } } | { InvalidName: { name: string; reason: string } } | { IntervalOutOfRange: { field: string; value: number } } | { DanglingRef: { what: string } } | 
/**
 * A Tailscale instance used by the exit is bound to a different interface than the exit.
 */
{ InterfaceMismatch: { exit: string; node: string } } | { InvalidProxy: { name: string; reason: string } } | 
/**
 * The generated config was rejected by `mihomo -t`.
 */
{ CoreRejected: { message: string } } | 
/**
 * 同一个进程名或同一条路径出现在多处：同类条目只能属于一条规则。
 */
{ DuplicateProcessRule: { exe_path: string } } | { InvalidExePath: { exe_path: string; reason: string } } | 
/**
 * 已启用规则里走代理的「节点 + 生效网卡」组合数超过上限。
 */
{ TooManyProcessRules: { max: number } } | { EmptyProcessRule: { rule: string } } | { AiAppProcess: { exe_path: string; app: string } }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
